/**
 * The sample the app ships (`seeds/meridian.json`), held to the figures of the
 * ledger it was written from.
 *
 * The bundle is generated by a script that is not in this repo, from one
 * typed source of sample facts. Nothing here shares code with that script: a
 * figure that holds below is carried by the rows themselves, worked out the
 * way the app keeps it (a deal's amount is the total of its newest sent quote,
 * else what was typed; weighted by its stage's odds).
 *
 * Every figure is true on the sample's own day, Tuesday 28 July 2026 at 09:35.
 * The bundle writes each date as days from that Tuesday, so the day itself is
 * 0 and nothing below reads a clock.
 *
 * That the rows install and that a database keeps the same figures is proved
 * on three engines in the engine's repo; this suite fails first, and here.
 */

import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import manifest from "../../manifest.json";
import bundle from "../../seeds/meridian.json";

type Value = unknown;
type Row = Record<string, Value>;
interface Moment {
  day: number;
  minutes: number | null;
}

const ROOT = join(__dirname, "..", "..");
/** The sample's own moment: day 0, 09:35. */
const NOW: Moment = { day: 0, minutes: 9 * 60 + 35 };

const isDoc = (value: Value): value is Record<string, Value> => typeof value === "object" && value !== null && !Array.isArray(value);
const moment = (value: Value): Moment | null => {
  if (!isDoc(value) || typeof value["@day"] !== "number") return null;
  const time = typeof value["@time"] === "string" ? value["@time"].split(":").map(Number) : null;
  return { day: value["@day"], minutes: time === null ? null : time[0]! * 60 + time[1]! };
};
const before = (a: Moment, b: Moment): boolean => a.day < b.day || (a.day === b.day && (a.minutes ?? 0) < (b.minutes ?? 0));
const ref = (value: Value): string | null => (isDoc(value) && typeof value["@ref"] === "string" ? value["@ref"] : null);
const person = (value: Value): string | null => (isDoc(value) && typeof value["@person"] === "string" ? value["@person"] : null);
/** Money as whole pence, so that no sum below is a float's. */
const pence = (value: Value): number => Math.round(Number(value) * 100);

const tables = new Map<string, Row[]>((bundle as { tables: { ref: string; rows: Row[] }[] }).tables.map((table) => [table.ref, table.rows]));
const rows = (table: string): Row[] => tables.get(table) ?? [];
const declared = new Map((manifest as unknown as { requiredSchema: { tables: { ref: string; columns: { ref: string; rules?: Record<string, unknown> }[] }[] } }).requiredSchema.tables.map((table) => [table.ref, table]));
const sample = (manifest as unknown as { sampleData: { file: string; people: { key: string; name: string; email: string; role: string }[]; teams: { name: string; lead: string; members: string[] }[] } }).sampleData;
const roles = (manifest as unknown as { roles: { key: string }[] }).roles.map((role) => role.key);

/* The figures, as the app keeps them. */
const odds = new Map(rows("stages").map((stage) => [String(stage["@label"]), Number(stage["odds"])]));
const quoteTotal = new Map<string, number>();
for (const line of rows("quote_lines")) {
  const quote = ref(line["document_id"])!;
  quoteTotal.set(quote, (quoteTotal.get(quote) ?? 0) + Math.round(Number(line["qty"]) * pence(line["rate"])));
}
const newestSent = new Map<string, Row>();
for (const quote of rows("quotes")) {
  if (quote["status"] !== "sent") continue;
  const deal = ref(quote["deal_id"])!;
  const held = newestSent.get(deal);
  if (held === undefined || before(moment(held["sent_at"])!, moment(quote["sent_at"])!)) newestSent.set(deal, quote);
}
const amount = (deal: Row): number => {
  const quote = newestSent.get(String(deal["@label"]));
  return quote === undefined ? pence(deal["typed_amount"]) : quoteTotal.get(String(quote["@label"]))!;
};
const weighted = (deal: Row): number => amount(deal) * odds.get(ref(deal["stage_id"])!)!;
const sum = (list: Row[], of: (row: Row) => number): number => list.reduce((total, row) => total + of(row), 0) / 100;
const deals = (state: string): Row[] => rows("deals").filter((deal) => deal["state"] === state);
const dealOf = (label: string): Row => rows("deals").find((deal) => deal["@label"] === `deal:${label}`)!;

describe("the sample is the one the manifest names", () => {
  it("is where `sampleData.file` says, for this app, in the format Adminium reads", () => {
    expect(sample.file).toBe("seeds/meridian.json");
    expect(existsSync(join(ROOT, sample.file))).toBe(true);
    expect((bundle as { format: string; app: string }).format).toBe("adminium.sample/1");
    expect((bundle as { format: string; app: string }).app).toBe((manifest as { key: string }).key);
  });

  it("ships every picture it names, byte for byte", () => {
    const assets = (bundle as unknown as { assets: Record<string, { file: string; sha256: string }> }).assets;
    expect(Object.keys(assets)).toEqual(["signature"]);
    for (const asset of Object.values(assets)) {
      expect(existsSync(join(ROOT, asset.file)), asset.file).toBe(true);
      expect(createHash("sha256").update(readFileSync(join(ROOT, asset.file))).digest("hex"), asset.file).toBe(asset.sha256);
    }
  });

  it("writes only tables and columns the app declares, and no number Adminium gives without gaps", () => {
    const unknown: string[] = [];
    for (const [table, list] of tables) {
      const shape = declared.get(table);
      if (shape === undefined) {
        unknown.push(table);
        continue;
      }
      const columns = new Set(shape.columns.map((column) => column.ref));
      const gapless = shape.columns.filter((column) => (column.rules?.["sequence"] as { gapless?: boolean } | undefined)?.gapless === true).map((column) => column.ref);
      for (const row of list) {
        for (const column of Object.keys(row)) if (!column.startsWith("@") && !columns.has(column)) unknown.push(`${table}.${column}`);
        for (const column of gapless) if (row[column] !== null) unknown.push(`${table}.${column} is numbered by the sample`);
      }
    }
    expect([...new Set(unknown)]).toEqual([]);
  });

  it("names a row only after it is written, and a person only by a key the manifest lists", () => {
    const people = new Set(sample.people.map((one) => one.key));
    const seen = new Set<string>();
    const wrong: string[] = [];
    const walk = (value: Value, at: string): void => {
      if (Array.isArray(value)) return value.forEach((one) => walk(one, at));
      if (!isDoc(value)) return;
      const named = ref(value);
      if (named !== null && !seen.has(named)) wrong.push(`${at} names "${named}" before it is written`);
      const who = person(value);
      if (who !== null && !people.has(who)) wrong.push(`${at} names a person "${who}" the manifest does not list`);
      for (const inner of Object.values(value)) walk(inner, at);
    };
    for (const [table, list] of tables) {
      for (const row of list) {
        for (const [column, value] of Object.entries(row)) if (column !== "@label") walk(value, `${table}.${column}`);
        if (typeof row["@label"] === "string") seen.add(row["@label"]);
      }
    }
    expect(wrong).toEqual([]);
  });

  it("brings sixteen people, each in one of the app's nine roles, and the sales team", () => {
    expect(sample.people).toHaveLength(16);
    expect(sample.people.filter((one) => !roles.includes(one.role))).toEqual([]);
    expect(new Set(sample.people.map((one) => one.role)).size).toBe(9);
    expect(new Set(sample.people.map((one) => one.key)).size).toBe(16);
    expect(sample.teams).toEqual([{ name: "Sales", lead: "ivy", members: ["dana", "priya", "sam", "leo"] }]);
  });
});

describe("the sample's rows are the ledger's", () => {
  it("has 678 rows in 68 tables: the ledger's 661 in 67, and the 17 list prices its quotes were written from", () => {
    const counts = Object.fromEntries([...tables].map(([table, list]) => [table, list.length]));
    expect(Object.keys(counts)).toHaveLength(68);
    expect(Object.values(counts).reduce((total, n) => total + n, 0)).toBe(678);
    expect(counts["price_list"]).toBe(17);
    expect(counts).toMatchObject({
      settings: 1, stages: 5, lost_reasons: 5, companies: 9, contacts: 13, territories: 4, territory_places: 9,
      deals: 40, deal_stage_changes: 66, deal_marks: 40, follow_ups: 16, activities: 26, quotes: 9, quote_lines: 31,
      comments: 7, enquiries: 17, shows: 1, saved_views: 6, saved_searches: 5, renewals: 13, referrals: 6, reps: 4,
      targets: 4, one_to_ones: 4, one_to_one_sessions: 9, coaching_plans: 4, coaching_areas: 8, actions: 25,
      meetings: 1, meeting_slots: 6, meeting_decisions: 3, threads: 4, thread_members: 10, messages: 12, starters: 1,
      starter_steps: 12, covers: 1, site_visits: 10, visit_notes: 2, visit_agreed: 6, showroom_spaces: 3,
      showroom_bookings: 9, samples: 8, sample_loans: 4, sample_chases: 3, display_pieces: 9, jobs: 8, crews: 2,
      crew_members: 5, vehicles: 3, job_visits: 19, sign_offs: 7, snags: 9, delivery_notes: 5, delivery_note_lines: 15,
      waste_removals: 5, feedback: 5, complaints: 7, warranty_claims: 5, vehicle_checks: 2, vehicle_faults: 3,
      fuel_fills: 7, time_sheets: 5, time_sheet_lines: 25, certificates: 23, subcontractors: 5, insurance_incidents: 5,
    });
    // Empty in the sample by decision: nobody snoozed a nudge, no mail waits, no helper, no note of cover; stock is Inventory's.
    for (const table of ["outbox", "nudge_snoozes", "deal_members", "cover_notes", "deal_stock_needs"]) expect(tables.has(table), table).toBe(false);
  });

  it("the board: 14 open deals, 286,300, weighted 156,562.50", () => {
    const open = deals("open");
    expect([open.length, sum(open, amount), sum(open, weighted)]).toEqual([14, 286300, 156562.5]);
  });

  it("Dana's board: 6 deals, 143,400, weighted 95,740", () => {
    const hers = deals("open").filter((deal) => person(deal["owner_id"]) === "dana");
    expect([hers.length, sum(hers, amount), sum(hers, weighted)]).toEqual([6, 143400, 95740]);
  });

  it("a quoted deal stands at its newest SENT version, whatever was approved since", () => {
    expect(["d1", "d2", "d9", "d14", "d5"].map((label) => amount(dealOf(label)) / 100)).toEqual([52800, 27500, 21500, 31000, 38000]);
    // d1's second version is approved and not sent: it counts for nothing yet.
    const d1 = rows("quotes").filter((quote) => ref(quote["deal_id"]) === "deal:d1");
    expect(d1.map((quote) => [quote["version"], quote["status"], quote["approval"]])).toEqual([[1, "sent", "none"], [2, "draft", "approved"]]);
    expect([rows("quotes").filter((quote) => quote["approval"] === "asked").length, rows("quotes").filter((quote) => quote["approval"] === "approved").length, rows("quotes").filter((quote) => quote["approval"] === "refused").length]).toEqual([1, 2, 1]);
  });

  it("every quote line names its list price, and a first version is at list", () => {
    const price = new Map(rows("price_list").map((one) => [String(one["@label"]), pence(one["list_rate"])]));
    const first = new Set(rows("quotes").filter((quote) => quote["version"] === 1).map((quote) => String(quote["@label"])));
    const under: string[] = [];
    for (const one of rows("quote_lines")) {
      // The list price is the price list's: the sample types none, Adminium copies it as the line goes in.
      expect(one["list_rate"], "a typed list price").toBeUndefined();
      const listed = price.get(ref(one["price_id"])!);
      expect(listed, String(one["position"])).toBeDefined();
      if (first.has(ref(one["document_id"])!) && pence(one["rate"]) !== listed) under.push(ref(one["document_id"])!);
    }
    expect(under).toEqual([]);
  });

  it("closed: 8 won for 130,000, 18 lost for 294,400; booked this year 81,600", () => {
    expect([deals("won").length, sum(deals("won"), amount)]).toEqual([8, 130000]);
    expect([deals("lost").length, sum(deals("lost"), amount)]).toEqual([18, 294400]);
    // The sample's day is 28 July: this year began 208 days before it.
    const thisYear = deals("won").filter((deal) => moment(deal["closed_at"])!.day >= -208);
    expect(sum(thisYear, amount)).toBe(81600);
  });

  it("every deal has its mark, every won deal its job, and each closed deal one opening in its history", () => {
    expect(rows("deal_marks").map((mark) => ref(mark["deal_id"])).sort()).toEqual(rows("deals").map((deal) => String(deal["@label"])).sort());
    expect(rows("jobs").map((job) => ref(job["deal_id"])).sort()).toEqual(deals("won").map((deal) => String(deal["@label"])).sort());
    const changes = new Map<string, number>();
    for (const change of rows("deal_stage_changes")) changes.set(ref(change["deal_id"])!, (changes.get(ref(change["deal_id"])!) ?? 0) + 1);
    for (const deal of [...deals("won"), ...deals("lost")]) expect(changes.get(String(deal["@label"])), String(deal["@label"])).toBe(1);
  });

  it("follow-ups: three of Dana's steps are late; nine aftercare calls", () => {
    const late = rows("follow_ups").filter((one) => one["kind"] === "step" && person(one["owner_id"]) === "dana" && one["done"] !== true && before(moment(one["due_at"])!, NOW));
    expect(late).toHaveLength(3);
    expect(rows("follow_ups").filter((one) => one["kind"] === "aftercare")).toHaveLength(9);
  });

  it("jobs: seven signed off, each with its sign-off; five snags not put right; numbers off the app's own series", () => {
    expect([rows("sign_offs").length, rows("jobs").filter((job) => job["state"] === "signed-off").length]).toEqual([7, 7]);
    expect(rows("snags").filter((snag) => snag["state"] !== "put-right")).toHaveLength(5);
    // A typed "J-01" would meet the first job anybody makes: the sample's are S-01 to S-08.
    expect(rows("jobs").map((job) => job["code"])).toEqual(["S-01", "S-02", "S-03", "S-04", "S-05", "S-06", "S-07", "S-08"]);
  });

  it("the crew's week: 123 hours on the job and 31 travelling, on five sheets all sent; one certificate has run out", () => {
    const lines = rows("time_sheet_lines");
    expect([lines.reduce((total, line) => total + Number(line["hours"]), 0), lines.reduce((total, line) => total + Number(line["travel_hours"]), 0)]).toEqual([123, 31]);
    expect(rows("time_sheets").map((sheet) => sheet["state"])).toEqual(["sent", "sent", "sent", "sent", "sent"]);
    const out = rows("certificates").filter((one) => moment(one["valid_until"]) !== null && moment(one["valid_until"])!.day < 0);
    expect(out).toHaveLength(1);
  });

  it("enquiries: five in the inbox and twelve from the show", () => {
    expect([rows("enquiries").filter((one) => one["show_id"] === undefined).length, rows("enquiries").filter((one) => one["show_id"] !== undefined).length]).toEqual([5, 12]);
  });

  it("the settings row goes in first and only into an empty table", () => {
    expect([...tables.keys()][0]).toBe("settings");
    expect(rows("settings")[0]).toMatchObject({ "@onlyIfEmpty": true, approval_threshold_pct: 5 });
  });
});
